from pathlib import Path
import json,html,re
p=Path(__file__).parent
out=p.parent
data=json.loads((p/'data.json').read_text())
parts=[]
def channel(key,label):return f'<label><input type="checkbox" data-channel="{key}" checked>{label}</label>'
def lab(id,title,description,stage,duration,channels='',extra='',kind=''):
    return f'''<div class="lab" id="lab-{id}" data-lab="{id}" data-duration="{duration}" data-kind="{kind}">
<div class="lab-heading"><span class="eyebrow">Interactive study / {id}</span><h3>{title}</h3><p>{description}</p></div>
<div class="stage {id}-stage">{stage}</div>{extra}
<div class="controls"><button data-play>Replay sequence</button><button data-pause disabled>Pause</button><button data-start>Start state</button><button data-end>End state</button></div>
<div class="channels">{channels}</div>
<div class="timeline"><label for="time-{id}">{'Progress' if kind=='progress' else 'Time'}</label><input id="time-{id}" data-time type="range" min="0" max="{100 if kind=='progress' else duration}" value="{100 if kind=='progress' else duration}" step="{0.1 if kind=='progress' else 1}"><output data-clock></output></div>
<p class="readout" data-readout></p><p class="status" data-status aria-live="polite">Ready. Replay, scrub, or use the study controls.</p></div>'''
def recipe(key,files):
    links=' · '.join(f'<a href="evidence/{f}">{f}</a>' for f in files)
    return f'<p class="source">Source: {links}</p><details><summary>Extracted values / implementation notes</summary><pre>{html.escape(json.dumps(data[key],indent=2))}</pre></details>'
def section(id,title,body):parts.append((id,title,f'<section id="{id}" class="chapter"><span class="eyebrow">Study {len(parts):02}</span><h2>{title}</h2>{body}</section>'))
section('overview','A catalog with several kinds of time.','''<p>Vestre combines a staged hero, reversible CSS controls, continuous media, native scrolling, scroll-driven card composition, and an unusually slow footer. Each runs on a different clock. The large moving furniture scenes are video content; the webpage separately animates their containers.</p><p><strong>This version is Next.js/React, Motion, Tailwind/CSS modules, Embla Carousel and Base UI.</strong> It is the live US homepage reached by visiting vestre.com on 7 October 2026. The audit distinguishes source values, runtime observations and offline reconstructions.</p>''')
hero='<div class="hero-shell"><div class="hero-art"><div class="slat-grid"></div></div><div class="hero-copy"><p data-hero-support class="hero-eyebrow">INTRODUCING</p><h3 class="hero-title" aria-label="Clipped headline study"></h3><p data-hero-support>Shade designed for public life</p><div data-hero-support><span class="demo-button">EXPLORE</span></div></div></div>'
section('hero','Let the letters lead. Let the media settle.','''<p>The background starts at scale 1.12, opacity 0.6 and 2px blur, then settles over 2400ms with cubic Bézier <code>(.22,1,.36,1)</code>. Each title character rises from 120% of its own height through a clipped word container over 800ms, using <code>(.33,1,.68,1)</code>. There is no per-character opacity fade.</p><p>Character delays are 25ms × global non-space character index + 80ms × word index. Supporting copy begins 320ms after the last character starts, not after it finishes. For GLADE, eyebrow/description/CTA start at 420/520/620ms and each fade over 600ms. This creates overlap rather than a rigid title-then-copy sequence.</p>'''+lab('hero','Hero composition','Exact source curves and sequencing with substitute geometric artwork and fonts. Toggle the mask to see where the letters actually begin.',hero,2400,channel('zoom','12% media settle')+channel('blur','2px blur')+channel('fade','Media opacity')+channel('stagger','Character stagger')+channel('clip','Word masks')+channel('support','Supporting fades'),'<div class="controls"><label>Title <select data-hero-title><option>GLADE</option><option>PUBLIC BELONGING</option></select></label></div>')+recipe('hero',['e693a111acb2493a.js']))
head='<div class="header-scroll" tabindex="0" aria-label="Scroll region for compact-header hysteresis"><div class="study-header"><div class="header-fill"></div><div class="study-logo"><span class="logo-fill"></span><span class="logo-word">vestre</span></div><span class="header-demo-links">PRODUCTS / PROJECTS / ABOUT</span></div><div class="header-scroll-content"><b>Scroll a little.</b><p>Compact above 24px.<br>Expand below 4px.</p><div>Keep scrolling, then return to the top.</div></div></div>'
section('header','Contract with hysteresis.','''<p>The fixed header compacts when scrollY exceeds 24px and stays compact until scrollY falls below 4px. That small dead zone prevents repeated toggles around one threshold. On desktop the header goes from 136px to 64px and the logo container from 96px to 44px. Narrow viewports start at 104px and an 80px logo.</p><p>The yellow block simultaneously shrinks to 16px tall and fades to zero. The wordmark remains. All those transitions take 320ms with <code>(.3,.6,0,1)</code>. The compact fill rises to opacity 0.3 with static 16px backdrop blur. Cover detection and menu state separately choose header colors.</p>'''+lab('header','Header, logo and fill','Source dimensions and CSS easing. Scroll the focusable region to test the 24px/4px thresholds, or replay the contraction.',head,320,channel('fill','Yellow block disappears')+channel('background','Compact background'),'<div class="controls"><label>Source layout <select data-header-width><option value="desktop">Desktop ≥768px</option><option value="narrow">Narrow &lt;768px</option></select></label></div>')+recipe('header',['b664f27371261aee.js','a0955bf8ab7df94c.css']))
exec((p/'chapters.py').read_text())
def inventory():
    rows=[('hero','Hero layers','Mount','800ms letters / 600ms support / 2400ms media'),('header','Compact header','Scroll thresholds','320ms; 24px / 4px hysteresis'),('mega','Desktop mega-menu','Hover / focus','320ms opacity; no stagger'),('accents','Underline, caret, market','Hover / open state','150 / 200ms'),('products','Product image crossfade','Hover','300ms opacity; no scale'),('media','Media hover variants','Hover','300 / 500ms; 2–4% zoom'),('gallery','Automatic image gallery','Continuous + drag','30px/s steady-state Embla'),('overlap','Overlapping story cards','Scroll progress','Linear mapping; no duration'),('rows','Articles + references','Buttons / native scroll','Browser-controlled smooth + snap'),('footer','Footer SVG track + groups','Continuous','120s track; 225–600s rotations'),('mobile','Narrow menu + subpanel','Open / close / drill','300ms panels; 150ms scrim'),('drawer','Search / help drawer','Open / close','450ms open; 400ms normal close'),('placeholder','Search hint characters','3-second interval','500ms + 20ms stagger'),('help','Floating greeting','Delayed + footer entry','3s wait / 6s visible; 300 / 200ms')]
    table='<div class="table-wrap"><table><thead><tr><th>Motion family / showcase</th><th>Trigger</th><th>Clock</th></tr></thead><tbody>'+''.join(f'<tr><td><a href="#lab-{id}">{title} ↘</a></td><td>{trigger}</td><td>{clock}</td></tr>' for id,title,trigger,clock in rows)+'</tbody></table></div>'
    id,title,body=parts[0];parts[0]=(id,title,body.replace('</section>',table+'</section>'))
inventory()
def render():
    nav=''.join(f'<a href="#{id}"><span>{i:02}</span>{title}</a>' for i,(id,title,body) in enumerate(parts))
    count=sum(body.count('data-lab=') for _,_,body in parts)
    doc='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>Vestre — Motion Audit & Interactive Showcase</title><style>'''+(p/'report.css').read_text()+'''</style></head><body><a class="skip-link" href="#main">Skip to audit</a><header class="topbar"><a href="#overview" class="brand">MOTION / VESTRE</a><span>Source + live browser evidence</span><a href="https://www.vestre.com/us" target="_blank" rel="noreferrer">Original site ↗</a></header><nav class="chapters" aria-label="Audit chapters">'''+nav+'''</nav><main id="main"><div class="cover"><span class="eyebrow">Motion showcase / study 05</span><h1>Vestre.</h1><p class="cover-title">Different clocks.<br>One composition.</p><p class="cover-sub">Letters, layers and slow geometry.<br>Measured from the delivered page.</p><div class="cover-meta"><span>07 Oct 2026</span><span>'''+str(count)+''' interactive studies</span><span>US homepage + narrow navigation</span></div></div><div class="global-controls"><label>Playback <select id="study-speed"><option value="1">1× original speed</option><option value=".5">0.5× slow</option><option value=".25">0.25× very slow</option><option value="2">2× fast</option><option value="10">10× · long loops</option></select></label><label><input id="study-reduce" type="checkbox">Reduced motion</label><button id="stop-all">Pause all studies</button><span>No autoplay. Begin a study when ready.</span></div>'''+''.join(body for _,_,body in parts)+'''<footer class="report-footer">Vestre homepage motion audit · 7 October 2026 · An independent study.</footer></main><script id="motion-data" type="application/json">'''+json.dumps(data).replace('</','<\\/')+'''</script><script>'''+(p/'report.js').read_text()+'''</script></body></html>'''
    (out/'motion-audit.html').write_text(doc)
    print(f'Built {len(parts)} chapters / {count} studies')
render()
